@font-face{ font-family:"Space Grotesk";src:url("https://www.dgeniussolutions.com/wp-content/cache/fonts/1/google-fonts/fonts/s/spacegrotesk/v22/V8mDoQDjQSkFtoMM3T6r8E7mPbF4Cw.woff2") format("woff2");font-weight:300 700;font-style:normal;font-display:swap; }

:root {
            --cyan-blue: #00D4FF;
            --magenta-pink: #FF00DC;
            --orange: #FF6B35;
        }

        *, *::before, *::after {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        body {
            background: #000000;
            color: white;
            font-family: 'Space Grotesk', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
            overflow-x: hidden;
            min-height: 100vh;
            display: flex;
            flex-direction: column;
        }

        /* ── ANIMATED MESH BACKGROUND ── */
        .gradient-bg {
            position: fixed;
            top: 0; left: 0;
            width: 100%; height: 100%;
            z-index: 0;
            opacity: 0.22;
            background:
                radial-gradient(circle at 15% 20%, rgba(0, 212, 255, 0.4) 0%, transparent 40%),
                radial-gradient(circle at 85% 60%, rgba(255, 0, 220, 0.35) 0%, transparent 40%),
                radial-gradient(circle at 50% 80%, rgba(255, 107, 53, 0.3) 0%, transparent 40%),
                radial-gradient(circle at 70% 10%, rgba(0, 212, 255, 0.25) 0%, transparent 35%);
            animation: meshMove 20s ease-in-out infinite;
            filter: blur(80px);
        }

        @keyframes meshMove {
            0%, 100% { transform: translate(0, 0) scale(1); opacity: 0.22; }
            33%       { transform: translate(30px, -30px) scale(1.05); opacity: 0.27; }
            66%       { transform: translate(-20px, 20px) scale(0.98); opacity: 0.24; }
        }

        /* ── FLOATING ORBS ── */
        .orbs {
            position: fixed;
            top: 0; left: 0;
            width: 100%; height: 100%;
            z-index: 0;
            pointer-events: none;
            overflow: hidden;
        }

        .orb {
            position: absolute;
            border-radius: 50%;
            filter: blur(40px);
            animation: float 15s ease-in-out infinite;
        }
        .orb:nth-child(1) {
            width: 400px; height: 400px;
            top: 5%; left: 5%;
            background: radial-gradient(circle at 30% 30%, rgba(0, 212, 255, 0.15), rgba(255, 0, 220, 0.05));
            animation-delay: 0s;
        }
        .orb:nth-child(2) {
            width: 300px; height: 300px;
            top: 55%; right: 8%;
            background: radial-gradient(circle at 30% 30%, rgba(255, 0, 220, 0.15), rgba(255, 107, 53, 0.05));
            animation-delay: 3s;
        }
        .orb:nth-child(3) {
            width: 260px; height: 260px;
            bottom: 10%; left: 12%;
            background: radial-gradient(circle at 30% 30%, rgba(255, 107, 53, 0.15), rgba(0, 212, 255, 0.05));
            animation-delay: 6s;
        }

        @keyframes float {
            0%, 100% { transform: translate(0, 0) scale(1); }
            33%       { transform: translate(30px, -40px) scale(1.1); }
            66%       { transform: translate(-25px, 30px) scale(0.9); }
        }

        /* ── PARTICLE CONFETTI ── */
        .particles {
            position: fixed;
            top: 0; left: 0;
            width: 100%; height: 100%;
            z-index: 0;
            pointer-events: none;
            overflow: hidden;
        }

        .particle {
            position: absolute;
            border-radius: 50%;
            opacity: 0;
            animation: particleFall linear infinite;
        }

        @keyframes particleFall {
            0%   { transform: translateY(-20px) rotate(0deg); opacity: 0; }
            10%  { opacity: 1; }
            90%  { opacity: 0.6; }
            100% { transform: translateY(110vh) rotate(720deg); opacity: 0; }
        }

        /* ── MAIN LAYOUT ── */
        .ty-section {
            position: relative;
            z-index: 1;
            min-height: 100vh;
            display: flex;
            align-items: center;
            justify-content: center;
            padding: clamp(40px, 6vw, 100px) clamp(16px, 5%, 60px);
        }

        .ty-container {
            max-width: 960px;
            width: 100%;
            display: flex;
            flex-direction: column;
            align-items: center;
            gap: 32px;
        }

        /* ── BADGE ── */
        .ty-badge {
            display: inline-flex;
            align-items: center;
            gap: 10px;
            padding: 12px 28px;
            background: rgba(255, 255, 255, 0.03);
            backdrop-filter: blur(20px);
            border: 1px solid rgba(0, 212, 255, 0.3);
            border-radius: 100px;
            font-size: 0.7rem;
            font-weight: 500;
            letter-spacing: 3px;
            text-transform: uppercase;
            color: var(--cyan-blue);
            box-shadow: 0 8px 32px rgba(0, 212, 255, 0.15);
            opacity: 0;
            animation: fadeUp 0.7s ease 0.2s forwards;
        }

        .ty-badge::before {
            content: '';
            width: 10px; height: 10px;
            background: linear-gradient(135deg, #10B981, var(--cyan-blue));
            border-radius: 50%;
            animation: pulse 2s cubic-bezier(0.4, 0, 0.6, 1) infinite;
            box-shadow: 0 0 20px rgba(0, 212, 255, 0.5);
        }

        @keyframes pulse {
            0%, 100% { opacity: 1; transform: scale(1); }
            50%       { opacity: 0.6; transform: scale(1.3); }
        }

        /* ── CHECKMARK ICON ── */
        .ty-check-wrap {
            position: relative;
            opacity: 0;
            animation: fadeUp 0.7s ease 0.4s forwards;
        }

        /* Nuclear override for Elementor/WordPress theme white backgrounds */
        .ty-check-wrap *,
        .ty-check-wrap *::before,
        .ty-check-wrap *::after {
            background-color: transparent !important;
            box-shadow: none !important;
            border: none !important;
            outline: none !important;
        }

        .ty-check-ring {
            width: clamp(80px, 14vw, 120px) !important;
            height: clamp(80px, 14vw, 120px) !important;
            border-radius: 50% !important;
            background: transparent !important;
            display: flex !important;
            align-items: center !important;
            justify-content: center !important;
            position: relative !important;
            isolation: isolate;
            overflow: hidden;
        }

        /* The dark circle fill as an inlined pseudo on the wrap instead */
        .ty-check-ring::before {
            content: '' !important;
            position: absolute !important;
            inset: 0 !important;
            border-radius: 50% !important;
            background: #080808 !important;
            z-index: 0 !important;
            border: none !important;
        }

        /* Spinning gradient ring — sits outside overflow:hidden using wrapper */
        .ty-check-wrap::before {
            content: '';
            position: absolute;
            inset: -3px;
            border-radius: 50%;
            background: conic-gradient(
                var(--cyan-blue) 0deg,
                var(--magenta-pink) 120deg,
                var(--orange) 240deg,
                var(--cyan-blue) 360deg
            );
            z-index: -1;
            animation: spinRing 4s linear infinite;
            opacity: 0.85;
        }

        @keyframes spinRing {
            from { transform: rotate(0deg); }
            to   { transform: rotate(360deg); }
        }

        .ty-check-ring svg {
            width: clamp(36px, 6vw, 52px) !important;
            height: clamp(36px, 6vw, 52px) !important;
            stroke-dasharray: 60;
            stroke-dashoffset: 60;
            animation: drawCheck 0.8s cubic-bezier(0.4, 0, 0.2, 1) 1s forwards;
            background: transparent !important;
            fill: none !important;
            position: relative !important;
            z-index: 1 !important;
        }

        /* Override any WP/Elementor global SVG styles */
        .ty-check-ring svg path,
        .ty-check-ring svg polyline,
        .ty-check-ring svg circle,
        .ty-check-ring svg rect {
            fill: none !important;
            background: transparent !important;
        }

        @keyframes drawCheck {
            to { stroke-dashoffset: 0; }
        }

        /* ── COUNTDOWN REDIRECT ── */
        .ty-countdown-wrap {
            display: flex;
            flex-direction: column;
            align-items: center;
            gap: 14px;
            opacity: 0;
            animation: fadeUp 0.7s ease 1.2s forwards;
        }

        .ty-countdown-ring {
            position: relative;
            width: 72px;
            height: 72px;
            display: flex;
            align-items: center;
            justify-content: center;
        }

        .ty-countdown-svg {
            position: absolute;
            inset: 0;
            width: 100%;
            height: 100%;
            transform: rotate(-90deg);
        }

        .ty-countdown-track {
            fill: none;
            stroke: rgba(255,255,255,0.06);
            stroke-width: 3;
        }

        .ty-countdown-progress {
            fill: none;
            stroke: url(#check-gradient);
            stroke-width: 3;
            stroke-linecap: round;
            stroke-dasharray: 125.66;
            stroke-dashoffset: 0;
            transition: stroke-dashoffset 1s linear;
        }

        .ty-countdown-num {
            font-size: 1.4rem;
            font-weight: 600;
            font-variant-numeric: tabular-nums;
            background: linear-gradient(135deg, var(--cyan-blue), var(--magenta-pink));
            -webkit-background-clip: text;
            -webkit-text-fill-color: transparent;
            background-clip: text;
            position: relative;
            z-index: 1;
        }

        .ty-countdown-text {
            font-size: 0.82rem;
            color: rgba(255,255,255,0.4);
            text-align: center;
            letter-spacing: 0.02em;
        }

        .ty-countdown-text strong {
            color: rgba(255,255,255,0.65);
        }

        .ty-countdown-text a {
            color: var(--cyan-blue);
            text-decoration: none;
            border-bottom: 1px solid rgba(0,212,255,0.3);
            transition: color 0.2s, border-color 0.2s;
            margin-left: 4px;
        }

        .ty-countdown-text a:hover {
            color: var(--magenta-pink);
            border-color: rgba(255,0,220,0.4);
        }

        .ty-countdown-cancelled {
            color: rgba(255,255,255,0.3) !important;
            font-style: italic;
        }

        /* ── HEADLINE ── */
        .ty-title {
            font-size: clamp(2.2rem, 7vw, 5.5rem);
            font-weight: 400;
            line-height: 1.1;
            letter-spacing: -0.03em;
            text-align: center;
            opacity: 0;
            animation: fadeUp 0.7s ease 0.6s forwards;
        }

        .ty-title .gradient-text {
            background: linear-gradient(135deg, var(--cyan-blue) 0%, var(--magenta-pink) 50%, var(--orange) 100%);
            background-size: 200% auto;
            -webkit-background-clip: text;
            -webkit-text-fill-color: transparent;
            background-clip: text;
            animation: gradientShift 8s ease infinite;
            font-weight: 300;
        }

        @keyframes gradientShift {
            0%, 100% { background-position: 0% 50%; }
            50%       { background-position: 100% 50%; }
        }

        /* ── SUBTITLE ── */
        .ty-subtitle {
            font-size: clamp(1rem, 2vw, 1.25rem);
            color: rgba(255, 255, 255, 0.5);
            max-width: 620px;
            text-align: center;
            line-height: 1.7;
            font-weight: 300;
            opacity: 0;
            animation: fadeUp 0.7s ease 0.8s forwards;
        }

        /* ── INFO CARDS ROW ── */
        .ty-cards {
            display: grid;
            grid-template-columns: repeat(3, 1fr);
            gap: clamp(12px, 2vw, 20px);
            width: 100%;
            opacity: 0;
            animation: fadeUp 0.7s ease 1s forwards;
        }

        .ty-card {
            background: rgba(255, 255, 255, 0.02);
            backdrop-filter: blur(40px);
            border: 1px solid rgba(255, 255, 255, 0.06);
            border-radius: 24px;
            padding: clamp(20px, 3vw, 32px) clamp(16px, 2.5vw, 28px);
            text-align: center;
            position: relative;
            overflow: hidden;
            transition: all 0.4s cubic-bezier(0.4, 0, 0.2, 1);
        }

        .ty-card::before {
            content: '';
            position: absolute;
            top: 0; left: 0; right: 0;
            height: 2px;
            background: linear-gradient(90deg, transparent, var(--c, var(--cyan-blue)), transparent);
            opacity: 0.6;
        }

        .ty-card:nth-child(1) { --c: var(--cyan-blue); }
        .ty-card:nth-child(2) { --c: var(--magenta-pink); }
        .ty-card:nth-child(3) { --c: var(--orange); }

        .ty-card:hover {
            background: rgba(255, 255, 255, 0.045);
            border-color: rgba(255, 255, 255, 0.12);
            transform: translateY(-4px);
        }

        .ty-card-icon {
            width: clamp(44px, 6vw, 56px);
            height: clamp(44px, 6vw, 56px);
            border-radius: 16px;
            background: rgba(255,255,255,0.04);
            border: 1px solid rgba(255,255,255,0.07);
            display: flex;
            align-items: center;
            justify-content: center;
            margin: 0 auto 16px;
        }

        .ty-card-icon svg {
            width: clamp(20px, 3vw, 26px);
            height: clamp(20px, 3vw, 26px);
            stroke: var(--c, var(--cyan-blue));
            fill: none;
            stroke-width: 1.5;
            stroke-linecap: round;
            stroke-linejoin: round;
        }

        .ty-card-title {
            font-size: clamp(0.85rem, 1.5vw, 1rem);
            font-weight: 600;
            color: rgba(255,255,255,0.9);
            margin-bottom: 6px;
            letter-spacing: -0.01em;
        }

        .ty-card-desc {
            font-size: clamp(0.75rem, 1.2vw, 0.85rem);
            color: rgba(255,255,255,0.4);
            line-height: 1.6;
            font-weight: 300;
        }

        /* ── DIVIDER ── */
        .ty-divider {
            width: 100%;
            height: 1px;
            background: linear-gradient(90deg, transparent, rgba(255,255,255,0.08), transparent);
            opacity: 0;
            animation: fadeUp 0.5s ease 1.2s forwards;
        }

        /* ── BOTTOM ROW ── */
        .ty-bottom {
            display: flex;
            align-items: center;
            justify-content: space-between;
            width: 100%;
            gap: 20px;
            flex-wrap: wrap;
            opacity: 0;
            animation: fadeUp 0.7s ease 1.3s forwards;
        }

        .ty-contact-hint {
            font-size: clamp(0.8rem, 1.4vw, 0.9rem);
            color: rgba(255,255,255,0.35);
            font-weight: 300;
        }

        .ty-contact-hint a {
            color: var(--cyan-blue);
            text-decoration: none;
            position: relative;
            transition: color 0.3s ease;
        }

        .ty-contact-hint a::after {
            content: '';
            position: absolute;
            bottom: -2px; left: 0;
            width: 0; height: 1px;
            background: linear-gradient(90deg, var(--cyan-blue), var(--magenta-pink));
            transition: width 0.3s ease;
        }

        .ty-contact-hint a:hover::after { width: 100%; }

        /* ── CTA BUTTONS ── */
        .ty-actions {
            display: flex;
            gap: 12px;
            flex-wrap: wrap;
        }

        .btn-primary {
            display: inline-flex;
            align-items: center;
            gap: 8px;
            padding: 14px 28px;
            background: linear-gradient(135deg, var(--cyan-blue), var(--magenta-pink));
            border: none;
            border-radius: 100px;
            font-family: 'Space Grotesk', sans-serif;
            font-size: clamp(0.8rem, 1.3vw, 0.9rem);
            font-weight: 500;
            color: #000;
            cursor: pointer;
            text-decoration: none;
            transition: all 0.35s cubic-bezier(0.4, 0, 0.2, 1);
            position: relative;
            overflow: hidden;
            letter-spacing: 0.01em;
        }

        .btn-primary::before {
            content: '';
            position: absolute;
            inset: 0;
            background: linear-gradient(135deg, var(--magenta-pink), var(--orange));
            opacity: 0;
            transition: opacity 0.35s ease;
        }

        .btn-primary:hover { transform: translateY(-2px); box-shadow: 0 12px 40px rgba(0,212,255,0.3); }
        .btn-primary:hover::before { opacity: 1; }
        .btn-primary span { position: relative; z-index: 1; }

        .btn-secondary {
            display: inline-flex;
            align-items: center;
            gap: 8px;
            padding: 13px 28px;
            background: rgba(255,255,255,0.03);
            backdrop-filter: blur(20px);
            border: 1px solid rgba(255,255,255,0.1);
            border-radius: 100px;
            font-family: 'Space Grotesk', sans-serif;
            font-size: clamp(0.8rem, 1.3vw, 0.9rem);
            font-weight: 400;
            color: rgba(255,255,255,0.7);
            cursor: pointer;
            text-decoration: none;
            transition: all 0.35s cubic-bezier(0.4, 0, 0.2, 1);
        }

        .btn-secondary:hover {
            background: rgba(255,255,255,0.06);
            border-color: rgba(0,212,255,0.3);
            color: #fff;
            transform: translateY(-2px);
        }

        /* ── SOCIAL ROW ── */
        .ty-social {
            display: flex;
            align-items: center;
            gap: 16px;
            opacity: 0;
            animation: fadeUp 0.7s ease 1.5s forwards;
        }

        .ty-social-label {
            font-size: 0.75rem;
            color: rgba(255,255,255,0.3);
            letter-spacing: 1.5px;
            text-transform: uppercase;
            font-weight: 400;
        }

        .ty-social-links {
            display: flex;
            gap: 10px;
        }

        .ty-social-link {
            width: 38px; height: 38px;
            border-radius: 50%;
            background: rgba(255,255,255,0.03);
            border: 1px solid rgba(255,255,255,0.07);
            display: flex;
            align-items: center;
            justify-content: center;
            text-decoration: none;
            transition: all 0.35s cubic-bezier(0.4, 0, 0.2, 1);
        }

        .ty-social-link:hover {
            background: rgba(0,212,255,0.08);
            border-color: rgba(0,212,255,0.3);
            transform: translateY(-3px);
        }

        .ty-social-link svg {
            width: 16px; height: 16px;
            fill: url(#social-gradient-ty);
        }

        /* ── ANIMATIONS ── */
        @keyframes fadeUp {
            from { opacity: 0; transform: translateY(24px); }
            to   { opacity: 1; transform: translateY(0); }
        }

        /* ── RESPONSIVE ── */
        @media (max-width: 768px) {
            .ty-cards {
                grid-template-columns: 1fr;
                max-width: 400px;
                margin: 0 auto;
            }

            .ty-bottom {
                flex-direction: column;
                align-items: flex-start;
                gap: 16px;
            }

            .ty-social {
                flex-direction: column;
                align-items: flex-start;
                gap: 12px;
            }
        }

        @media (max-width: 480px) {
            .ty-actions {
                width: 100%;
                flex-direction: column;
            }

            .btn-primary, .btn-secondary {
                justify-content: center;
                width: 100%;
            }

            .ty-cards {
                grid-template-columns: 1fr 1fr;
                max-width: 100%;
            }

            .ty-cards .ty-card:last-child {
                grid-column: span 2;
            }
        }

        @media (max-width: 360px) {
            .ty-cards {
                grid-template-columns: 1fr;
            }

            .ty-cards .ty-card:last-child {
                grid-column: span 1;
            }
        }

/* ========================================
   FOOTER - LIGHTWEIGHT & SEXY DESIGN
   ======================================== */

.dgs-footer-wrapper * {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

.dgs-footer-wrapper {
  position: relative;
  background: transparent;
  padding: 0;
  margin: 0;
  font-family: 'Space Grotesk', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  overflow: hidden;
}

.dgs-footer {
  position: relative;
  background: transparent;
  border-top: 1px solid rgba(255, 255, 255, 0.05);
  padding: clamp(60px, 8vw, 100px) clamp(20px, 4vw, 40px) 0;
  color: #fff;
  overflow: hidden;
}

.dgs-footer-container {
  max-width: 1600px;
  margin: 0 auto;
  position: relative;
  z-index: 2;
}

.dgs-footer-grid {
  display: grid;
  grid-template-columns: 1.2fr repeat(3, 1fr);
  gap: clamp(30px, 4vw, 40px);
  margin-bottom: clamp(40px, 5vw, 55px);
}

.dgs-footer-column {
  display: flex;
  flex-direction: column;
}

.dgs-footer-logo-column {
  max-width: 280px;
}

.dgs-footer-logo {
  display: block;
  width: clamp(130px, 15vw, 160px);
  height: auto;
  margin-bottom: 22px;
  transition: transform 0.4s ease;
  opacity: 0.95;
}

.dgs-footer-logo:hover {
  transform: scale(1.03);
  opacity: 1;
}

.dgs-footer-tagline {
  font-size: clamp(0.8rem, 1.2vw, 0.88rem);
  font-weight: 300;
  color: rgba(255, 255, 255, 0.5);
  letter-spacing: 0.3px;
  margin-top: 0;
  margin-bottom: 22px;
  line-height: 1.7;
}

.dgs-footer-column-title {
  font-size: clamp(0.95rem, 1.5vw, 1.1rem);
  font-weight: 400;
  color: rgba(255, 255, 255, 0.95);
  margin-bottom: clamp(16px, 2vw, 20px);
  letter-spacing: 0.5px;
  position: relative;
  display: inline-block;
  width: fit-content;
}

.dgs-footer-column-title::after {
  content: '';
  position: absolute;
  bottom: -6px;
  left: 0;
  width: 30px;
  height: 1px;
  background: linear-gradient(90deg, #00D4FF 0%, #FF00DC 50%, #FF6B35 100%);
  border-radius: 10px;
  opacity: 0.6;
}

.dgs-footer-links {
  list-style: none;
  padding: 0;
  margin: 0;
}

.dgs-footer-link-item {
  margin-bottom: 8px;
}

.dgs-footer-link {
  display: inline-block;
  font-size: clamp(0.82rem, 1.2vw, 0.9rem);
  font-weight: 300;
  color: rgba(255, 255, 255, 0.55);
  text-decoration: none;
  transition: all 0.3s ease;
  position: relative;
  padding-left: 0;
  letter-spacing: 0.3px;
}

.dgs-footer-link::before {
  content: '→';
  position: absolute;
  left: -18px;
  opacity: 0;
  color: #FF6B35;
  transition: all 0.3s ease;
  font-weight: 300;
}

.dgs-footer-link:hover {
  color: rgba(255, 255, 255, 0.95);
  padding-left: 18px;
}

.dgs-footer-link:hover::before {
  opacity: 1;
  left: 0;
}

.dgs-footer-contact-item {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  margin-bottom: 14px;
  font-size: clamp(0.82rem, 1.2vw, 0.9rem);
  font-weight: 300;
  color: rgba(255, 255, 255, 0.65);
  line-height: 1.7;
}

.dgs-footer-contact-item div {
  text-align: left;
}

.dgs-footer-contact-icon {
  flex-shrink: 0;
  width: 18px;
  height: 18px;
  margin-top: 3px;
  opacity: 1;
  background: transparent !important;
}

.dgs-footer-contact-icon path {
  fill: none !important;
  background: none !important;
}

.dgs-footer-contact-item strong {
  font-weight: 400;
  color: rgba(255, 255, 255, 0.85);
}

.dgs-footer-contact-link {
  color: rgba(255, 255, 255, 0.65);
  text-decoration: none;
  transition: all 0.3s ease;
  display: block;
  margin-bottom: 6px;
  font-weight: 300;
}

.dgs-footer-contact-link:hover {
  color: rgba(255, 255, 255, 0.95);
  padding-left: 6px;
}

.dgs-footer-map-container {
  margin-top: 12px;
  max-height: 0;
  overflow: hidden;
  opacity: 0;
  transition: all 0.5s ease;
  border-radius: 12px;
}

.dgs-footer-map-container.active {
  max-height: 350px;
  opacity: 1;
  margin-top: 16px;
}

.dgs-footer-map-container iframe {
  width: 100%;
  height: 300px;
  border: 0;
  border-radius: 12px;
  display: block;
}

.dgs-footer-address-clickable {
  cursor: pointer;
  transition: all 0.3s ease;
}

.dgs-footer-address-clickable:hover {
  color: rgba(255, 255, 255, 0.95);
}

.dgs-footer-address-clickable strong {
  position: relative;
  display: inline-block;
}

.dgs-footer-address-clickable strong::after {
  content: ' ↗';
  font-size: 0.85em;
  opacity: 0.6;
  transition: all 0.3s ease;
}

.dgs-footer-address-clickable:hover strong::after {
  opacity: 1;
  transform: translateX(2px) translateY(-2px);
}

.dgs-footer-social {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
  margin-top: 0;
}

.dgs-footer-social-link {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  background: transparent;
  border: 1px solid rgba(255, 255, 255, 0.15);
  border-radius: 10px;
  color: rgba(255, 255, 255, 0.6);
  text-decoration: none;
  transition: all 0.4s ease;
}

.dgs-footer-social-link:hover {
  background: transparent;
  border-color: rgba(255, 107, 53, 0.5);
  transform: translateY(-3px);
  box-shadow: 0 6px 20px rgba(255, 107, 53, 0.15);
  color: rgba(255, 255, 255, 0.95);
}

.dgs-footer-social-icon {
  width: 18px;
  height: 18px;
}

.dgs-footer-stalk-box {
  margin-top: 18px;
  width: 100%;
}

.dgs-footer-stalk-title {
  font-size: clamp(0.82rem, 1.2vw, 0.92rem);
  font-weight: 500;
  color: rgba(255, 255, 255, 0.82);
  letter-spacing: 0.3px;
  margin-bottom: 12px;
  line-height: 1.35;
}

.dgs-footer-contact-column .dgs-footer-social {
  justify-content: flex-start;
}

.dgs-footer-contact-column .dgs-footer-social-link {
  width: 38px;
  height: 38px;
  border-radius: 10px;
  background: rgba(255, 255, 255, 0.035);
}

/* AI Summary Shortcut Icons - Latest Brand Icons */
.dgs-footer-ai-summary {
  margin: 0 0 22px;
  width: 100%;
}

.dgs-footer-ai-heading {
  font-size: clamp(0.76rem, 1.1vw, 0.84rem);
  font-weight: 400;
  color: rgba(255, 255, 255, 0.72);
  letter-spacing: 0.25px;
  margin-bottom: 10px;
  line-height: 1.45;
}

.dgs-footer-ai-icons {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
}

.dgs-footer-ai-link {
  width: 36px;
  height: 36px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 10px;
  border: 1px solid rgba(255, 255, 255, 0.16);
  background: rgba(255, 255, 255, 0.065);
  text-decoration: none;
  transition: all 0.35s ease;
  position: relative;
  overflow: hidden;
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
}

.dgs-footer-ai-link::before {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, rgba(0, 212, 255, 0.18), rgba(255, 0, 220, 0.14), rgba(255, 107, 53, 0.18));
  opacity: 0;
  transition: opacity 0.35s ease;
}

.dgs-footer-ai-link:hover {
  transform: translateY(-3px);
  border-color: rgba(255, 107, 53, 0.55);
  box-shadow: 0 8px 24px rgba(255, 107, 53, 0.18);
}

.dgs-footer-ai-link:hover::before {
  opacity: 1;
}

.dgs-footer-ai-icon {
  position: relative;
  z-index: 1;
  width: 19px;
  height: 19px;
  display: block;
  object-fit: contain;
  filter: drop-shadow(0 2px 4px rgba(0, 0, 0, 0.22));
}

.dgs-footer-ai-fallback {
  position: relative;
  z-index: 1;
  display: none;
  align-items: center;
  justify-content: center;
  width: 100%;
  height: 100%;
  color: rgba(255, 255, 255, 0.92);
  font-size: 0.68rem;
  font-weight: 700;
  line-height: 1;
  letter-spacing: 0.2px;
}

.dgs-ai-prompt-toast {
  position: fixed;
  left: 50%;
  bottom: 24px;
  transform: translateX(-50%) translateY(20px);
  z-index: 999999;
  max-width: min(92vw, 420px);
  padding: 12px 16px;
  border-radius: 14px;
  background: rgba(10, 10, 14, 0.92);
  border: 1px solid rgba(255, 255, 255, 0.14);
  box-shadow: 0 14px 40px rgba(0, 0, 0, 0.35);
  color: rgba(255, 255, 255, 0.92);
  font-size: 0.82rem;
  line-height: 1.45;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.28s ease, transform 0.28s ease;
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
}

.dgs-ai-prompt-toast.active {
  opacity: 1;
  transform: translateX(-50%) translateY(0);
}


.dgs-footer-ai-top {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 16px;
  flex-wrap: wrap;
  margin: 0 0 clamp(32px, 4vw, 45px);
  padding: 16px 20px;
  border-radius: 18px;
  background: rgba(255, 255, 255, 0.045);
  border: 1px solid rgba(255, 255, 255, 0.11);
  box-shadow: 0 14px 38px rgba(0, 0, 0, 0.18);
}

.dgs-footer-ai-top .dgs-footer-ai-heading {
  margin-bottom: 0;
  text-align: center;
}


.dgs-footer-trust-badges {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
  margin: 8px 0 22px;
}

.dgs-footer-trust-badge {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  width: fit-content;
  max-width: 100%;
  min-height: 58px;
  padding: 9px 14px 9px 10px;
  border-radius: 14px;
  background: rgba(255, 255, 255, 0.055);
  border: 1px solid rgba(255, 255, 255, 0.14);
  box-shadow: 0 10px 28px rgba(0, 0, 0, 0.18);
  transition: all 0.35s ease;
}

.dgs-footer-trust-badge:hover {
  transform: translateY(-2px);
  border-color: rgba(255, 107, 53, 0.45);
  box-shadow: 0 12px 30px rgba(255, 107, 53, 0.18);
}

.dgs-footer-trust-logo-wrap {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 74px;
  height: 42px;
  padding: 4px 6px;
  border-radius: 10px;
  background: #ffffff;
  overflow: hidden;
  flex-shrink: 0;
}

.dgs-footer-trust-logo-wrap img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: contain;
}

.dgs-footer-trust-copy {
  display: flex;
  flex-direction: column;
  justify-content: center;
  line-height: 1.15;
  text-align: left;
}

.dgs-footer-trust-title {
  font-size: 0.78rem;
  font-weight: 600;
  color: rgba(255, 255, 255, 0.96);
  letter-spacing: 0.2px;
  margin-bottom: 3px;
}

.dgs-footer-trust-stars {
  font-size: 0.82rem;
  font-weight: 500;
  color: #ff6b35;
  letter-spacing: 0.8px;
  margin-bottom: 3px;
}

.dgs-footer-trust-subtext {
  font-size: 0.68rem;
  font-weight: 300;
  color: rgba(255, 255, 255, 0.58);
  letter-spacing: 0.25px;
}

.dgs-footer-bottom {
  border-top: 1px solid rgba(255, 255, 255, 0.05);
  padding: clamp(20px, 3vw, 28px) 0;
  text-align: center;
}

.dgs-footer-copyright {
  font-size: clamp(0.75rem, 1.2vw, 0.85rem);
  font-weight: 300;
  color: rgba(255, 255, 255, 0.45);
  letter-spacing: 0.5px;
  margin-bottom: 10px;
}

.dgs-footer-copyright-gradient {
  background: linear-gradient(90deg, #00D4FF 0%, #FF00DC 50%, #FF6B35 100%);
  background-size: 200% 100%;
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
  animation: gradientSlideFooter 8s linear infinite;
  font-weight: 400;
}

.dgs-footer-legal-links {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 20px;
  flex-wrap: wrap;
}

.dgs-footer-legal-link {
  font-size: clamp(0.75rem, 1.2vw, 0.82rem);
  font-weight: 300;
  color: rgba(255, 255, 255, 0.45);
  text-decoration: none;
  transition: all 0.3s ease;
  letter-spacing: 0.3px;
}

.dgs-footer-legal-link:hover {
  color: rgba(255, 255, 255, 0.85);
}

.dgs-footer-legal-divider {
  color: rgba(255, 255, 255, 0.25);
  font-weight: 300;
}

@keyframes gradientSlideFooter {
  0% { background-position: 0% 50%; }
  100% { background-position: 200% 50%; }
}

@media (max-width: 1100px) {
  .dgs-footer-grid {
    grid-template-columns: repeat(2, 1fr);
    gap: clamp(28px, 4vw, 35px);
  }

  .dgs-footer-trust-badges {
    justify-content: center;
  }

  .dgs-footer-logo-column {
    grid-column: 1 / -1;
    max-width: 100%;
    text-align: center;
    align-items: center;
  }

  .dgs-footer-logo {
    margin-left: auto;
    margin-right: auto;
  }

  .dgs-footer-social {
    justify-content: center;
  }

  .dgs-footer-ai-summary {
    text-align: center;
  }

  .dgs-footer-ai-icons {
    justify-content: center;
  }
}

@media (max-width: 968px) {
  .dgs-footer {
    padding: clamp(50px, 7vw, 70px) clamp(20px, 4vw, 30px) 0 !important;
  }

  .dgs-footer-grid {
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: 30px;
  }

  .dgs-footer-column {
    text-align: center;
    align-items: center;
  }

  .dgs-footer-column-title::after {
    left: 50%;
    transform: translateX(-50%);
  }

  .dgs-footer-link::before {
    display: none;
  }

  .dgs-footer-link:hover {
    padding-left: 0;
  }

  .dgs-footer-contact-item {
    flex-direction: column;
    align-items: center;
    text-align: center;
    gap: 8px;
  }

  .dgs-footer-contact-item div {
    text-align: center;
  }

  .dgs-footer-contact-icon {
    margin-top: 0;
  }

  .dgs-footer-social {
    justify-content: center;
  }
}


  .dgs-footer-contact-column .dgs-footer-social {
    justify-content: center;
  }

  .dgs-footer-stalk-box {
    text-align: center;
  }

@media (max-width: 580px) {
  .dgs-footer {
    padding: 45px 20px 0 !important;
  }

  .dgs-footer-trust-badges {
    justify-content: center;
    gap: 10px;
    margin-bottom: 20px;
  }

  .dgs-footer-trust-badge {
    padding: 9px 12px 9px 9px;
    gap: 10px;
  }

  .dgs-footer-trust-logo-wrap {
    width: 68px;
    height: 40px;
  }

  .dgs-footer-trust-title {
    font-size: 0.74rem;
  }

  .dgs-footer-trust-stars {
    font-size: 0.78rem;
  }

  .dgs-footer-trust-subtext {
    font-size: 0.64rem;
  }

  .dgs-footer-grid {
    grid-template-columns: 1fr;
    gap: 28px;
  }

  .dgs-footer-legal-links {
    flex-direction: column;
    gap: 10px;
  }

  .dgs-footer-legal-divider {
    display: none;
  }



  .dgs-footer-ai-top {
    flex-direction: column;
    gap: 12px;
    margin-bottom: 30px;
    padding: 16px;
  }
  .dgs-footer-map-container iframe {
    height: 250px;
  }
}
